import sys, struct, re, os
from elftools.elf.elffile import ELFFile
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_ARM
from capstone.arm64 import ARM64_OP_IMM, ARM64_OP_REG

class ELFX:
    def __init__(self, path):
        self.path = path
        self.f = open(path, 'rb')
        self.e = ELFFile(self.f)
        self.exec_secs = []
        self.all_secs = []
        for s in self.e.iter_sections():
            if s['sh_type'] == 'SHT_NOBITS' or s['sh_size'] == 0:
                continue
            data = s.data()
            self.all_secs.append((s['sh_addr'], s['sh_size'], data, s.name))
            if s['sh_flags'] & 0x4:
                self.exec_secs.append((s['sh_addr'], s['sh_size'], data))
        # PLT map from relocations
        self.plt = {}
        dynsym = self.e.get_section_by_name('.dynsym')
        # find real dynsym: sh_type SHT_DYNSYM
        dynsym = None
        for s in self.e.iter_sections():
            if s['sh_type'] == 'SHT_DYNSYM':
                dynsym = s
                break
        for s in self.e.iter_sections():
            if s['sh_type'] == 'SHT_RELA' and dynsym is not None:
                symtab = dynsym
                for rel in s.iter_relocations():
                    info = rel['r_info_type']
                    if info in (0x402, 0x401):  # JUMP_SLOT/GLOB_DAT
                        sym = symtab.get_symbol(rel['r_info_sym'])
                        if sym.name:
                            self.plt[rel['r_offset']] = sym.name
        # dynsym names by addr (for internal funcs exported)
        self.dyn_by_addr = {}
        if dynsym is not None:
            for sym in dynsym.iter_symbols():
                if sym['st_value']:
                    self.dyn_by_addr.setdefault(sym['st_value'], sym.name)

    def read_str(self, addr, maxlen=200):
        for base, size, data, name in self.all_secs:
            if base <= addr < base + size:
                off = addr - base
                end = data.find(b'\x00', off)
                if end == -1 or end - off > maxlen:
                    end = min(off + maxlen, len(data))
                try:
                    return data[off:end].decode('utf-8', errors='replace')
                except Exception:
                    return repr(data[off:end])
        return None

    def read_data(self, addr, n):
        for base, size, data, name in self.all_secs:
            if base <= addr < base + size:
                off = addr - base
                return data[off:off+n]
        return None

    def code_at(self, addr, size):
        for base, sz, data in self.exec_secs:
            if base <= addr < base + sz:
                off = addr - base
                return data[off:off+size]
        return None

def adrp_target(insn_addr, word):
    immhi = (word >> 5) & 0x7ffff
    immlo = (word >> 29) & 0x3
    imm = (immhi << 2) | immlo
    if imm & 0x100000:
        imm -= 0x200000
    return (insn_addr & ~0xfff) + (imm << 12)

def disasm(ex, start, size, annotate=True):
    code = ex.code_at(start, size)
    if code is None:
        print(f"!! addr {start:#x} not in any exec section")
        return
    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
    md.detail = True
    pages = {}  # reg -> page
    lines = []
    for ins in md.disasm(code, start):
        comment = ""
        if ins.mnemonic == 'adrp':
            page = adrp_target(ins.address, struct.unpack_from('<I', code, ins.address - start)[0])
            pages[ins.reg_name(ins.operands[0].reg)] = page
            comment = f" ; page={page:#x}"
        elif ins.mnemonic == 'add' and len(ins.operands) == 3 and ins.operands[2].type == ARM64_OP_IMM:
            rn = ins.reg_name(ins.operands[1].reg)
            if rn in pages:
                tgt = pages[rn] + ins.operands[2].imm
                s = ex.read_str(tgt)
                if s and all(32 <= ord(c) < 127 for c in s[:1]):
                    comment = f" ; {tgt:#x} \"{s[:120]}\""
                else:
                    comment = f" ; ->{tgt:#x}"
        elif ins.mnemonic in ('bl', 'b') and ins.operands[0].type == ARM64_OP_IMM:
            tgt = ins.operands[0].imm
            name = ex.plt.get(tgt) or ex.dyn_by_addr.get(tgt)
            if name:
                comment = f" ; <{name}>"
        elif ins.mnemonic == 'ldr' and len(ins.operands) == 2 and ins.operands[1].type == ARM64_OP_IMM:
            pass
        lines.append(f"0x{ins.address:08x}:  {ins.mnemonic:<7} {ins.op_str}{comment}")
    return lines

def find_xrefs(ex, target, window_page=True):
    """Find ADRP+ADD pairs that form `target` address."""
    hits = []
    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
    md.detail = True
    tpage = target & ~0xfff
    tlo = target & 0xfff
    for base, size, data in ex.exec_secs:
        pages = {}
        for ins in md.disasm(data, base):
            if ins.mnemonic == 'adrp':
                page = adrp_target(ins.address, struct.unpack_from('<I', data, ins.address - base)[0])
                pages[ins.reg_name(ins.operands[0].reg)] = (page, ins.address)
            elif ins.mnemonic == 'add' and len(ins.operands) == 3 and ins.operands[2].type == ARM64_OP_IMM:
                rn = ins.reg_name(ins.operands[1].reg)
                if rn in pages and pages[rn][0] == tpage and ins.operands[2].imm == tlo:
                    hits.append(ins.address)
            elif ins.mnemonic == 'ldr' and ins.operands[1].type == ARM64_OP_IMM:
                # literal pool
                lit = ins.operands[1].imm
                d = ex.read_data(lit, 8)
                if d and struct.unpack('<Q', d)[0] == target:
                    hits.append(ins.address)
    return hits

if __name__ == '__main__':
    cmd = sys.argv[1]
    path = os.environ.get('TARGET')
    ex = ELFX(path)
    if cmd == 'dis':
        start = int(sys.argv[2], 16)
        size = int(sys.argv[3], 0) if sys.argv[3].startswith('0x') else int(sys.argv[3])
        label = sys.argv[4] if len(sys.argv) > 4 else ''
        print(f"===== {label} {start:#x}..{start+size:#x} =====")
        for l in disasm(ex, start, size):
            print(l)
    elif cmd == 'xref':
        target = int(sys.argv[2], 16)
        for h in find_xrefs(ex, target):
            print(hex(h))
    elif cmd == 'str':
        print(ex.read_str(int(sys.argv[2], 16)))

